  "Välj en fröpåse. Vattna bädden varje dag – två dagar utan vatten och plantorna vissnar. Skörden hamnar i skafferiet.": "Wybierz torebkę nasion. Podlewaj grządkę codziennie – dwa dni bez wody i roślinki uschną. Plony trafią do spiżarni.",
